def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each horizontal stripe is a row in a six-row repeating sequence;
    # zero rows are missing stripes to be restored from the other cycles.
    if all(len(set(row)) == 1 for row in grid):
        period = 6
        phases = {}
        for r, row in enumerate(grid):
            color = row[0]
            if color != 0:
                phase = r % period
                if phase in phases and phases[phase] != color:
                    # Fully observed/nonperiodic stripe sequences are unchanged.
                    return [row[:] for row in grid]
                phases[phase] = color
        if not phases:
            return [row[:] for row in grid]
        return [[phases.get(r % period, 0)] * w for r in range(h)]
    return [row[:] for row in grid]
